import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const PLAN_STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
// 가정: 상신으로 만드는 결재문서의 연계 업무 유형 값
const LINKED_BUSINESS_TYPE = 'annual_leave_plan';

@Controller('api/v1')
export class FnSfr03204Controller {
  @Post('/annual-leave-plans/:annualLeavePlanId/submit')
  @HttpCode(200)
  async submitAnnualLeavePlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const planId = req.params['annualLeavePlanId'];
    if (!/^\d+$/.test(planId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차계획 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT annual_leave_plan_id AS "annualLeavePlanId", plan_status AS "planStatus", plan_month AS "planMonth" FROM annual_leave_plan WHERE annual_leave_plan_id = CAST(:planId AS bigint) FOR UPDATE',
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_PLAN_NOT_FOUND', '연차계획을 찾을 수 없습니다.');
      }
      const plan = plans[0];
      if (plan.planStatus !== '기안') {
        throw new ApiError(409, 'ANNUAL_LEAVE_PLAN_NOT_SUBMITTABLE', '기안 상태의 연차계획만 상신할 수 있습니다.');
      }
      // 가정: 연계 결재 양식 중 사용 중인 첫 양식을 쓴다
      const forms = await db.query(
        'SELECT approval_form_id AS "approvalFormId" FROM approval_form WHERE use_status = \'사용\' AND is_linked_approval = true ORDER BY approval_form_id LIMIT 1',
        {},
      );
      const drafters = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (forms.length === 0 || drafters.length === 0 || drafters[0].departmentId === null) {
        throw new ApiError(502, 'APPROVAL_LINK_FAILED', '전자결재 상신에 실패했습니다.');
      }
      // 가정: 문서번호는 연차계획 ID로 만든다
      const docs = await db.query(
        'INSERT INTO approval_document (approval_form_id, drafter_id, drafter_department_id, document_number, title, approval_status, is_urgent, is_secret, linked_business_type, linked_business_id, submitted_at, created_at, updated_at) ' +
          'VALUES (CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint), \'AL-\' || CAST(CAST(:planId AS bigint) AS text), :title, \'결재대기\', false, false, :linkedType, CAST(:planId AS bigint), now(), now(), now()) ' +
          'RETURNING approval_document_id AS "approvalDocumentId"',
        {
          formId: forms[0].approvalFormId,
          userId: user.id,
          departmentId: drafters[0].departmentId,
          planId,
          title: '연차계획 결재 상신 (' + plan.planMonth + ')',
          linkedType: LINKED_BUSINESS_TYPE,
        },
      );
      const approvalDocumentId = docs[0].approvalDocumentId;
      await db.execute(
        'UPDATE annual_leave_plan SET plan_status = \'결재대기\', approval_document_id = CAST(:docId AS bigint), updated_at = now() WHERE annual_leave_plan_id = CAST(:planId AS bigint)',
        { docId: approvalDocumentId, planId },
      );
      return { planStatus: '결재대기', approvalDocumentId };
    });
  }

  @Post('/annual-leave-plans/approval-result')
  @HttpCode(200)
  async reflectAnnualLeavePlanApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    const data = checks.inputOf(req.body);
    const docId = data['approvalDocumentId'];
    const status = data['planStatus'];
    if (!/^\d+$/.test(String(docId ?? ''))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서는 숫자여야 합니다.');
    }
    if (typeof status !== 'string' || !PLAN_STATUSES.includes(status)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '계획 상태가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'UPDATE annual_leave_plan SET plan_status = :status, updated_at = now() WHERE approval_document_id = CAST(:docId AS bigint) RETURNING annual_leave_plan_id AS "annualLeavePlanId", plan_status AS "planStatus"',
        { status, docId: String(docId) },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_PLAN_NOT_FOUND', '결재문서에 연결된 연차계획이 없습니다.');
      }
      return { annualLeavePlanId: rows[0].annualLeavePlanId, planStatus: rows[0].planStatus };
    });
  }
}

response.page:
import { useState } from 'react';
import {
  ApiFail,
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  NumberInput,
  Pager,
  RefName,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const STATUSES: [string, string][] = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'].map((s) => [s, s]);
const STAGES: [string, string][] = [['1차', '1차'], ['2차', '2차']];

export default function FnSfr03204Page({ role, notify }: PageProps) {
  const [planMonth, setPlanMonth] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<'plan' | 'promotion' | 'result' | null>(null);
  const [form, setForm] = useState<Row>({});

  const plans = useData<Page>(
    () => call<Page>('GET', '/annual-leave-plans', role, undefined, { ...applied, page, size: 10 }),
    [role, applied, page],
  );
  const promotions = useData<Page>(
    () => call<Page>('GET', '/leave-promotions', role, undefined, { page: 0, size: 5 }),
    [role],
  );

  const open = (kind: 'plan' | 'promotion' | 'result') => {
    setForm({});
    setDrawer(kind);
  };
  const set = (key: string, value: unknown) => setForm((prev) => ({ ...prev, [key]: value }));

  const submitPlan = async (row: Row) => {
    try {
      await call('POST', '/annual-leave-plans/' + row.annualLeavePlanId + '/submit', role, {});
      notify('결재를 상신했습니다.');
      plans.reload();
    } catch (e) {
      notify(e instanceof ApiFail ? e.message : '상신에 실패했습니다.');
    }
  };

  const savePlan = async () => {
    if (!form.employeeId || !form.planMonth || !form.planDate) {
      throw new Error('임직원, 계획 연월, 계획 일자를 모두 입력해 주세요.');
    }
    await call('POST', '/annual-leave-plans', role, form);
    notify('연차계획을 등록했습니다.');
    setDrawer(null);
    plans.reload();
  };

  const savePromotion = async () => {
    if (!form.annualLeaveId || !form.employeeId || !form.promotionStage || !form.noticeDate) {
      throw new Error('연차, 촉진 대상 임직원, 촉진 단계, 통보일을 모두 입력해 주세요.');
    }
    await call('POST', '/leave-promotions', role, form);
    notify('연차촉진을 실행했습니다.');
    setDrawer(null);
    promotions.reload();
  };

  const saveResult = async () => {
    if (form.approvalDocumentId === undefined || form.approvalDocumentId === '' || !form.planStatus) {
      throw new Error('결재문서와 계획 상태를 입력해 주세요.');
    }
    await call('POST', '/annual-leave-plans/approval-result', role, form);
    notify('결재 결과를 반영했습니다.');
    setDrawer(null);
    plans.reload();
  };

  const planData = plans.data;
  const promoData = promotions.data;

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>연차계획</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ planMonth, employeeId });
          }}
          onReset={() => {
            setPlanMonth('');
            setEmployeeId('');
            setPage(0);
            setApplied({});
          }}
        >
          <Field label="계획 연월">
            <TextInput value={planMonth} onChange={setPlanMonth} placeholder="YYYY-MM" />
          </Field>
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        <Band total={planData?.total}>
          <button onClick={() => open('plan')}>계획 등록</button>
          <button onClick={() => open('result')}>결재 결과 반영</button>
        </Band>
        <DataTable
          rows={planData?.items ?? []}
          empty={plans.error || '연차계획이 없습니다.'}
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'planMonth', label: '계획 연월' },
            { key: 'planDate', label: '계획 일자', render: (r) => <DateText value={r.planDate} /> },
            { key: 'planStatus', label: '계획 상태', render: (r) => <Badge value={r.planStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r.planStatus === '기안' ? <button onClick={() => submitPlan(r)}>결재 상신</button> : null,
            },
          ]}
        />
        <Pager page={page} size={10} total={planData?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>최근 연차촉진</h2>
        <Band total={promoData?.total}>
          <button onClick={() => open('promotion')}>촉진 실행</button>
        </Band>
        <DataTable
          rows={promoData?.items ?? []}
          empty={promotions.error || '촉진 내역이 없습니다.'}
          columns={[
            { key: 'employeeId', label: '촉진 대상 임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'promotionStage', label: '촉진 단계', render: (r) => <Badge value={r.promotionStage} /> },
            { key: 'noticeDate', label: '통보일', render: (r) => <DateText value={r.noticeDate} /> },
          ]}
        />
      </section>

      {drawer === 'plan' && (
        <Drawer title="월별 연차계획 등록" onClose={() => setDrawer(null)}>
          <Form onSubmit={savePlan} submit="등록">
            <Field label="임직원" required>
              <LookupSelect table="employee" role={role} value={form.employeeId} onChange={(v) => set('employeeId', v)} />
            </Field>
            <Field label="계획 연월" required hint="YYYY-MM">
              <TextInput value={form.planMonth} onChange={(v) => set('planMonth', v)} />
            </Field>
            <Field label="계획 일자" required>
              <DateInput value={form.planDate} onChange={(v) => set('planDate', v)} />
            </Field>
          </Form>
        </Drawer>
      )}

      {drawer === 'promotion' && (
        <Drawer title="연차촉진 실행" onClose={() => setDrawer(null)}>
          <Form onSubmit={savePromotion} submit="실행">
            <Field label="연차" required>
              <LookupSelect table="annual_leave" role={role} value={form.annualLeaveId} onChange={(v) => set('annualLeaveId', v)} />
            </Field>
            <Field label="촉진 대상 임직원" required>
              <LookupSelect table="employee" role={role} value={form.employeeId} onChange={(v) => set('employeeId', v)} />
            </Field>
            <Field label="촉진 단계" required>
              <Select value={form.promotionStage} onChange={(v) => set('promotionStage', v)} options={STAGES} />
            </Field>
            <Field label="통보일" required>
              <DateInput value={form.noticeDate} onChange={(v) => set('noticeDate', v)} />
            </Field>
          </Form>
        </Drawer>
      )}

      {drawer === 'result' && (
        <Drawer title="결재 결과 반영" onClose={() => setDrawer(null)}>
          <Form onSubmit={saveResult} submit="반영">
            <Field label="결재문서" required>
              <NumberInput value={form.approvalDocumentId} onChange={(v) => set('approvalDocumentId', v)} />
            </Field>
            <Field label="계획 상태" required>
              <Select value={form.planStatus} onChange={(v) => set('planStatus', v)} options={STATUSES} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
